INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(77, 'plPL', 'Lepka sytuacja', 'Posiadam oryginalne materiały do pakowania sikacza, którego szuka Dran Droffers. Pomogę ci zapakować sikacz dla tego szorstkiego ojca Maltona... za opłatą w postaci dwóch dodatkowych butelek rzeczonego sikacza. Znajdują się one w skrzyniach w opuszczonej bazie Hordy przy Skale Skradaczy.$B$BZadanie to będzie żmudne, mianowicie: do ruin przylgnęły plugawe śluzy i szlamy; wieść niesie, że przewodzi im jakiś szlam nad szlamami. Tak czy inaczej, zdobądź sikacz i wróć tu do mnie, a zajmę się pakowaniem.', 'Odzyskaj 10 butelek miodowego sikacza z Zaziemia ze skrzyń rozstawionych w opuszczonej bazie Hordy przy Skale Skradaczy.', '', 'Wróć do Gilveradina Słońcogona w Obozie Shindiggera w Zaziemiu.', '', '', '', '', 0),
(485, 'plPL', 'Znajdź OOX-09/HL!', '$GOdkryłeś:Odkryłaś; jakieś dziwne, jajowate urządzenie z metalu. Gdy majstrujesz przy jednym z pokręteł, jajo ożywa i rozkłada się w coś w rodzaju gnomiej robotycznej maszynerii! Z wnętrza robotycznego jaja dobiega trzeszczący głos.$B$B„Nazywam się Oglethorpe Obnoticus i rozbił mi się samonaprowadzający robot! Nagrodzę cię za jego odzyskanie; proszę, zanieś ten sygnalizator do robota!”$B$B„Właśnie obliczyłem dla ciebie współrzędne robota; rozbił się u źródeł rzeki niedaleko Skały Skradaczy!”', 'Zanieś sygnalizator alarmowy do samonaprowadzającego robota Oglethorpe\'a u źródeł rzeki w Zaziemiu, niedaleko Skały Skradaczy.', '', '', '', '', '', '', 0),
(1446, 'plPL', 'Jammal\'an Prorok', 'Moi towarzysze z Suchokorych nie witają życzliwie obcych w pobliżu swojego domu.$b$bJa? Ja już nie mam domu. Zostałem wygnany przez mój lud, wielkie plemię Atal\'ai z Moczarów Smutków.$b$bNasz duchowy przywódca, Jammal\'an, miał coś, co nazwał proroctwem. Wierzy, że przyzwanie boga Hakkara zapewni Atal\'ai nieśmiertelność.$b$bAle ja wzywałem do ostrożności. A jeśli to proroctwo było tylko manipulacją?$b$bPragnę zemsty za moje wygnanie. Przynieś mi głowę Jammal\'ana. Może wtedy mój lud będzie wolny.', 'Wygnaniec Atal\'ai w Zaziemiu chce dostać głowę Jammal\'ana.', '', 'Wróć do wygnańca Atal\'ai w Shadra\'Alor w Zaziemiu.', '', '', '', '', 0),
(1450, 'plPL', 'Mistrz gryfów Szponotopór', 'A więc jesteś tylko $gchłopcem:dziewczyną; na posyłki jakiegoś starego dziada z Ligi Odkrywców, co?$b$bTo posłuchaj mnie, $N. Nie wiem, z kim twój stary kumpel latał tam na dole, w Azeroth. Czy ja ci wyglądam na mistrza gryfów Szponotopora? Wyglądam?$b$bSkoro tak cię interesują przydziały lotów, to czemu nie spytasz mistrza gryfów? Jeśli jeszcze długo będę cię tu widział, jak się obijasz, to zagonię cię do prawdziwej roboty.$b$bA teraz zmykaj.', 'Porozmawiaj z mistrzem gryfów Szponotoporem w Awiarium Orlego Gniazda.', '', '', '', '', '', '', 0),
(1451, 'plPL', 'Rhapsody Shindigger', 'Rhapsody bardzo zasmakował w gorzale. Nie zrozum mnie źle – wszyscy tu, w awiarium, kochamy dobre piwo we właściwej chwili.$b$bAle stary Shindigger rzucił się na trunki jak gryf w przestworza. I cholerna szkoda. Nikt nie latał tak jak Rhapsody.$b$bPierwszy niepokojący znak pojawił się, kiedy wrócił, zataczając się, z tamtej misji z twoim kumplem Brohannem. Potem wszystko szybko potoczyło się w dół. Musiałem go zwolnić.$b$bOstatnio słyszałem, że rozbił obóz piwowarski na wschód stąd...', 'Odszukaj Rhapsody\'ego Shindiggera w Zaziemiu.', '', '', '', '', '', '', 0),
(1452, 'plPL', 'Kalimdorski Koktajl Rhapsody\'ego', 'Hep!$b$bTo ten szalony głupek Brohann cię przysłał? Ależ mieliśmy przygodę... Hep!$b$bJak chcesz, żebym ci opowiedział, co się stało tam na bagnach, to będę potrzebował czegoś mocnego do picia. To nie był ładny widok, rozumiesz. Hep!$b$bWiesz co... przynieś mi, czego trzeba, żebym zmieszał Kalimdorski Koktajl, a opowiem ci wszystko.$b$bBędą mi potrzebne żołądki roków z Tanaris... i zaraz, zaraz... wątroby małp Groddoc i żelaznoskórych niedźwiedzi z Feralas...$b$bPorządny, mocny Kalimdorski Koktajl... po nim się rozgadam!', 'Rhapsody Shindigger w Zaziemiu chce, żebyś $gprzyniósł:przyniosła; mu 3 żołądki roka, 3 wątroby małpy Groddoc i 3 wątroby żelaznoskórego niedźwiedzia.', '', 'Wróć do Rhapsody\'ego Shindiggera w Zaziemiu.', '', '', '', '', 0),
(2742, 'plPL', 'Rin\'ji uwięziony!', 'Hej, $r!$B$BRin\'ji zgubił topór i dał się złapać! Proszę, pomóż Rin\'jiemu uciec. Rin\'ji wie, że $r jak ty nie lubi takich jak Rin\'ji, ale Rin\'ji błaga! Musi się stąd wydostać!$B$BRin\'ji ma coś dla ciebie, jeśli $gbędziesz dobry:będziesz dobra; i pomożesz Rin\'jiemu stąd wyjść...$B$BRin\'ji ukrył coś tajnego na Urwiskach Widokowych.', 'Odeskortuj Rin\'jiego ze Stróżówki Quel\'Danil, a następnie znajdź jego ukryty sekret na Urwiskach Widokowych na wschodzie.', 'Odeskortuj Rin\'jiego w bezpieczne miejsce', 'Znajdź sekret Rin\'jiego na Urwiskach Widokowych w Zaziemiu.', '', '', '', '', 0),
(2877, 'plPL', 'Porządki przy Skale Skradaczy', 'My, Dzikie Młoty, pamiętamy przeszłość lepiej niż nasi bracia z Żelaznej Kuźni. Jeśli chcesz mieć tu przyjaciół, to pobrudź sobie dla nas ręce!$B$BHorda porzuciła swoje pozycje w Zaziemiu wokół Skały Skradaczy; teraz roi się tam od paskudnych brei i szlamów. Mamy plany wobec tamtego terenu, ale najpierw potrzebujemy ekipy sprzątającej, która zrobi nam przejście.$B$BI tu wkraczasz ty, słoneczko! Ruszaj tam i wybij dziesięć zielonych brei i dziesięć nefrytowych szlamów, a potem zamelduj się u mnie. Wymarsz!', 'Zabij 10 zielonych brei i 10 nefrytowych szlamów, a następnie zamelduj się u Fraggara Gromopłaszcza w Orlim Gnieździe.', '', 'Wróć do Fraggara Gromopłaszcza w Orlim Gnieździe w Zaziemiu.', '', '', '', '', 0),
(2880, 'plPL', 'Nagroda za trollowe naszyjniki', 'Zapamiętaj to sobie, $r – NIE należymy do Przymierza! Dzikie Młoty są niezależne i o czyjejś wartości świadczą dla nas czyny, a nie gadanina tych, którzy trajkotaniem podpierają swoje nicnierobienie!$B$BJeśli szukasz tu przyjaciół, to najpierw udowodnij nam swoją wartość! Plugawe trolle, które zapychają zbocza Zaziemia, czasem noszą plemienne naszyjniki. Przynieś mi pięć takich, a zapiszemy ci to jako krok we właściwym kierunku.', 'Przynieś 5 plemiennych naszyjników trolli Fraggarowi Gromopłaszczowi w Orlim Gnieździe.', '', 'Wróć do Fraggara Gromopłaszcza w Orlim Gnieździe w Zaziemiu.', '', '', '', '', 0),
(2881, 'plPL', 'Nagroda za trollowe naszyjniki', '', '', '', 'Wróć do Fraggara Gromopłaszcza w Zaziemiu.', '', '', '', '', 0),
(2988, 'plPL', 'Klatki Suchokorych', 'Córka naszego najpotężniejszego gryfa zaginęła! Dziedziczka Rączego Wiatru, Ostrodzioba, przepadła kilka dni temu podczas polowania z rodzicami i sądzimy, że porwały ją trolle.$B$BMusisz nam pomóc! Przeszukaj klatki w dwóch wioskach trolli Suchokorych i sprawdź, czy jest tam Ostrodzioba.', 'Sprawdź klatki w dwóch wioskach Suchokorych, a następnie wróć do mistrza gryfów Szponotopora.', '', 'Wróć do mistrza gryfów Szponotopora w Orlim Gnieździe w Zaziemiu.', 'Sprawdź pierwszą klatkę', 'Sprawdź drugą klatkę', 'Sprawdź trzecią klatkę', '', 0),
(2989, 'plPL', 'Ołtarz Zula', 'Ostrodziobej nie było u trolli Suchokorych. Może porwały ją trolle Plugawego Konaru. Idź do Ołtarza Zula na zachodnim skraju terytorium Plugawego Konaru i poszukaj tam gryfiego pisklęcia.', 'Sprawdź szczyt Ołtarza Zula, a następnie wróć do mistrza gryfów Szponotopora.', 'Przeszukaj Ołtarz Zula', 'Wróć do mistrza gryfów Szponotopora w Orlim Gnieździe w Zaziemiu.', '', '', '', '', 0),
(2990, 'plPL', 'Thadius Ponury Cień', 'Zanieś to pióro Thadiusowi Ponuremu Cieniowi, wróżbicie. Wiele lat temu opuścił Orle Gniazdo, by zgłębiać mroczniejszą wiedzę, ale w sercu wciąż jest Dzikim Młotem!$B$BMoże jego talenty pomogą nam odnaleźć Ostrodziobą.$B$BTo pióro zabrano z gniazda, w którym śpi gryfie pisklę. Jeśli dasz je Thadiusowi, to przy odrobinie szczęścia zdoła odnaleźć Ostrodziobą swoją magią wieszczenia.$B$BPowodzenia, $N. Thadiusa znajdziesz na Jałowych Ziemiach, w wieży magów Strażnicy Otchłani.', 'Zanieś pióro Ostrodziobej Thadiusowi Ponuremu Cieniowi na Jałowych Ziemiach.', '', '', '', '', '', '', 0),
(2992, 'plPL', 'Wieszczenie', 'Zrób mi miejsce, gdy będę odprawiał rytuał wieszczenia. Odnajdę więź między piórem, które mi $gprzyniosłeś:przyniosłaś;, a jego właścicielką i podążę tą więzią aż do samej Ostrodziobej.$B$BTo znaczy... odnajdę, jeśli wszystko pójdzie zgodnie z planem. Jeśli nie, to... lepiej zamknij oczy.', 'Zaczekaj, aż Ponury Cień odprawi rytuał wieszczenia.', 'Zaczekaj, aż Ponury Cień skończy', 'Wróć do Thadiusa Ponurego Cienia w Strażnicy Otchłani na Jałowych Ziemiach.', '', '', '', '', 0),
(2993, 'plPL', 'Powrót do Zaziemia', 'Ostrodzioba jest zamknięta w klatce wysoko na urwisku, na szczycie Jintha\'Alor w Zaziemiu. Klucz do tej klatki ma najwyższa kapłanka trolli Plugawego Konaru, Plugawa kapłanka Hexx.$B$BProszę. Zrobiłem swoje. Życzę ci szczęścia w twojej misji, $N.', 'Porozmawiaj z mistrzem gryfów Szponotoporem.', '', '', '', '', '', '', 0),
(2994, 'plPL', 'Ratunek dla Ostrodziobej', 'Musimy uratować Ostrodziobą!$B$BPrzebij się na szczyt Jintha\'Alor, w samym sercu terytorium Plugawego Konaru, zdobądź klucz do klatki Ostrodziobej od plugawej kapłanki Hexx, a potem znajdź i uratuj Ostrodziobą!', 'Przebij się na szczyt Jintha\'Alor, zabij Plugawą kapłankę Hexx, by zdobyć klucz do klatki Ostrodziobej, i uratuj Ostrodziobą.', '', 'Wróć do mistrza gryfów Szponotopora w Orlim Gnieździe w Zaziemiu.', '', 'Otwórz klatkę Ostrodziobej', '', '', 0),
(4297, 'plPL', 'Jedzenie dla malucha', 'Duszkowce są wszystkożerne – znaczy, jedzą i mięso, i rośliny. Jeśli to twoje jajo ma się wykluć, lepiej się przygotujmy. Dobre żarcie dla tych maluchów to, wierz lub nie, udźce mięsa, surowe i soczyste. Nigdy nie udało mi się dowiedzieć czemu, ale ma to coś wspólnego z planem Eluny wobec elfów... może miały być ich obrońcami czy coś, nie wiem.$B$BNa razie zajmę się jajem, a ty może przyniesiesz mi parę dobrych udźców srebrnogrzywych tropicieli, żeby maluch miał co jeść, jak się wykluje.', 'Przynieś 5 udźców srebrnogrzywego tropiciela Agnarowi Poskramiaczowi Bestii w Zaziemiu.', '', 'Wróć do Agnara Poskramiacza Bestii w Zaziemiu.', '', '', '', '', 0),
(4298, 'plPL', 'Zostać rodzicem', 'Ojej, było o wiele bardziej gotowe, niż myślałem...', 'Porozmawiaj z Agnarem Poskramiaczem Bestii w Zaziemiu.', '', '', '', '', '', '', 0),
(4787, 'plPL', 'Prastare jajo', 'Proroctwo Mosh\'aru mówi o prastarym jaju. To relikt z czasów, gdy trolle władały ogromnymi imperiami, i ma ono moc pomieszczenia esencji Hakkara. To może być jedyny sposób, by ochronić nasz świat przed jego złem.$B$BPrzynieś mi prastare jajo, $N. Podobno jest ukryte głęboko w Jintha\'Alor w Zaziemiu, w jaskini za amfiteatrem na szczycie miasta.', 'Przynieś prastare jajo Yeh\'kinyi w Tanaris.', '', 'Wróć do Yeh\'kinyi w Porcie Parochlebców w Tanaris.', '', '', '', '', 0),
(7815, 'plPL', 'Kłapacze, mon!', 'Nie daj się zwieść ich wielkim oczom, mon! Te słonowodne kłapacze to utrapienie. Nie mogę łowić nawet pięciu minut, żeby jeden z tych przerośniętych rybnych odkurzaczy nie ukradł mi przynęty i nie zerwał żyłki.$B$BZrób przysługę mnie i mieszkańcom Wioski Odsłoniętego Kła i pozabijaj je, mon.$B$BWybij całą tę zgraję!', 'Katoom Wędkarz z Wioski Odsłoniętego Kła w Zaziemiu chce, żebyś $gzabił:zabiła; 10 żółwi – słonowodnych kłapaczy. Wróć do niego, gdy wykonasz to zadanie.', '', 'Wróć do Katooma Wędkarza w Wiosce Odsłoniętego Kła w Zaziemiu.', '', '', '', '', 0),
(7816, 'plPL', 'Gammerita, mon!', 'Hej! Jest tam jedna żółwica, nie taka jak inne. To Gammerita, przywódczyni słonowodnych kłapaczy – podła, złodziejska gadzina.$B$BMon, ukradła moją najlepszą przynętę. Odgryzła mi ją prosto z żyłki! Od tamtej pory ryby już nie biorą tak jak kiedyś.$B$BZnajdź Gammeritę i wyciągnij moją przynętę z jej brzucha.', 'Katoom Wędkarz z Wioski Odsłoniętego Kła w Zaziemiu chce, żebyś $gzabił:zabiła; Gammeritę i $godzyskał:odzyskała; z jej zwłok najlepszą przynętę Katooma.$B$BKatoom wspomniał, że Gammerita przesiaduje na wybrzeżu z innymi żółwiami.', '', 'Wróć do Katooma Wędkarza w Wiosce Odsłoniętego Kła w Zaziemiu.', '', '', '', '', 0),
(7828, 'plPL', 'Tropienie tropicieli', 'Wielu dzielnych trolli zginęło w surowej dziczy Zaziemia, $r. Srebrnogrzywe wilki to jedno z największych zagrożeń dla naszych łowców. Czają się ukryte w krzakach i w terenie, a potem uderzają, gdy tylko nadarzy się okazja.$B$BTaka dzikość nie może pozostać bez odpowiedzi!$B$BMusisz myśleć jak srebrnogrzywy. Wytrop tropicieli! Wybij ich wszystkich!', 'Myśliwy Markhor z Wioski Odsłoniętego Kła w Zaziemiu chce, żebyś $gzabił:zabiła; 5 srebrnogrzywych tropicieli i 5 srebrnogrzywych wyjców. Wróć do niego, gdy wykonasz zadanie.$B$BMarkhor wspomniał, że wilki kryją się w dziczy Zaziemia.', '', 'Wróć do myśliwego Markhora w Wiosce Odsłoniętego Kła w Zaziemiu.', '', '', '', '', 0),
(7829, 'plPL', 'Polowanie na dzikusów', 'Wśród najbardziej krnąbrnych zwierząt Zaziemia są dzikie sowostwory. Niejeden dobry wojownik Odsłoniętego Kła padł od okrutnych pazurów i dziobów tych bestii.$B$BZabij każdego dzikiego sowostwora, jakiego zobaczysz, $N. Wróć do mnie, gdy nie zniesiesz już więcej rozlewu krwi. Wtedy twój wkład zostanie zważony, zmierzony i osądzony.', 'Myśliwy Markhor z Wioski Odsłoniętego Kła w Zaziemiu chce, żebyś $gzabił:zabiła; 10 dzikich sowostworów. Wróć do niego, gdy wykonasz zadanie.$B$BMarkhor wspomniał, że dzikie sowostwory zamieszkują dzicz Zaziemia.', '', 'Wróć do myśliwego Markhora w Wiosce Odsłoniętego Kła w Zaziemiu.', '', '', '', '', 0),
(7830, 'plPL', 'Pomścić poległych', 'Plugastwo, co zwie się Dzikim Młotem, szkoli gryfa, by zabijał trolla. Straszne, wiem, ale nie martw się, sprawiedliwości wkrótce stanie się zadość.$B$BNa razie chcę, żebyś $gskupił:skupiła; się na wybiciu starszych gryfów w okolicy. Zwą je władcami przestworzy.$B$BZabij jednego i wróć do mnie z jego piórem.', 'Myśliwy Markhor z Wioski Odsłoniętego Kła w Zaziemiu chce, żebyś $gzabił:zabiła; brzytwodziobego władcę przestworzy i $gzdobył:zdobyła; jego pióro władcy przestworzy. Wróć do niego, gdy wykonasz zadanie.$B$BMarkhor wspomniał, że brzytwodzioby władca przestworzy to rzadki gatunek, który zwykle zamieszkuje dzicz Zaziemia.', '', 'Wróć do myśliwego Markhora w Wiosce Odsłoniętego Kła w Zaziemiu.', '', '', '', '', 0),
(7839, 'plPL', 'Chuligani z Plugawego Konaru', 'Szumowiny z Plugawego Konaru najechały naszą wioskę i ukradły mi narzędzia! Mam zapasowe, ale ten komplet, który ukradli, dostałem w prezencie od dobrodusznego gnoma, który uratował mi życie, kiedy byłem młodym orkiem.$B$BChcę odzyskać te narzędzia, $N – znaczą dla mnie wszystko.$B$BMarkhor doniósł, że narzędzia widziano w pobliżu świątyń Agol\'watha i Shaol\'watha.$B$BTe świątynie są w północno-wschodniej części Zaziemia.$B$BOdzyskaj moje narzędzia!', 'Kowal Żużlodrzew z Wioski Odsłoniętego Kła w Zaziemiu chce, żebyś $godnalazł:odnalazła; zgubione narzędzia Żużlodrzewa. Wróć do niego, gdy wykonasz zadanie.$B$BPamiętasz, że kowal Żużlodrzew wspominał, iż narzędzia mogą być w jednej ze świątyń Plugawego Konaru w północno-wschodniej części Zaziemia. Warto też sprawdzić Skałę Skradaczy.', '', 'Wróć do kowala Żużlodrzewa w Wiosce Odsłoniętego Kła w Zaziemiu.', '', '', '', '', 0),
(7840, 'plPL', 'Smalec zgubił obiad', 'Smalec być w tajnym specjalnym miejscu na piknik, a brzydki zły troll z Plugawego Konaru walnąć Smalca wielkim kijem. Smalec uciec do Odsłoniętego Kła, ale zapomnieć obiad Smalca. Smalec głodny. Może ty wrócić do tajnego specjalnego miejsca i przynieść obiad Smalca? Smalec się bać. Idź na północ! Wyspa tam na północy to tajne specjalne miejsce.', 'Smalec z Wioski Odsłoniętego Kła w Zaziemiu chce, żebyś $godnalazł:odnalazła; obiad Smalca. Wróć do niego, gdy wykonasz zadanie.$B$BSmalec wspomniał, że zostawił go na wyspie na północy. Uważaj na trolle Plugawego Konaru.', '', 'Wróć do Smalca w Wiosce Odsłoniętego Kła w Zaziemiu.', '', '', '', '', 0),
(7841, 'plPL', 'Wiadomość do klanu Dzikiego Młota', 'Dzikie Młoty dobijają targu z naszymi wrogami, zawierają nowe sojusze. Tym razem, mon, współpracują z wysokimi elfami.$B$B<Otho spluwa.>$B$BMusimy wysłać tym krasnoludom z klanu Dzikiego Młota wiadomość – wiadomość wypisaną krwią naszych wrogów. Wyrżnij każdego wysokiego elfa z Wysokiej Doliny, jakiego napotkasz, a ich ciała zostaw jako ostrzeżenie.$B$BZ trollami się nie zadziera!', 'Otho Moji\'ko z Wioski Odsłoniętego Kła w Zaziemiu chce, żebyś $gwyrżnął:wyrżnęła; 8 zwiadowców z Wysokiej Doliny, 5 zwiadowczyń z Wysokiej Doliny, 5 tropicielek z Wysokiej Doliny i 2 strzelców z Wysokiej Doliny. Wróć do niego, gdy wykonasz zadanie.$B$BWysokie elfy z Wysokiej Doliny znajdziesz w Stróżówce Quel\'Danil w północno-zachodniej części Zaziemia.', '', 'Wróć do Otha Moji\'ko w Wiosce Odsłoniętego Kła w Zaziemiu.', '', '', '', '', 0),
(7842, 'plPL', 'Kolejna wiadomość do klanu Dzikiego Młota', 'Mówią, że Dzikie Młoty i gryfy są sobie tak bliskie jak troll i jego partnerka. Obrzydliwe, ale możemy to obrócić na naszą korzyść, mon. Wyślemy im kolejną wiadomość.$B$BZabijaj wszystkie gryfy, jakie zobaczysz w Zaziemiu, i zdobądź długie eleganckie pióro! Z niego zrobimy ostatnią wiadomość.', 'Otho Moji\'ko z Wioski Odsłoniętego Kła w Zaziemiu chce, żebyś $gprzyniósł:przyniosła; mu 1 długie eleganckie pióro od gryfów zamieszkujących Zaziemie. Wróć do niego, gdy wykonasz zadanie.$B$BGryfy zamieszkują każdą część Zaziemia.', '', 'Wróć do Otha Moji\'ko w Wiosce Odsłoniętego Kła w Zaziemiu.', '', '', '', '', 0),
(7843, 'plPL', 'Ostatnia wiadomość do klanu Dzikiego Młota', '<Otho wręcza ci długą, zbroczoną krwią włócznię owiniętą kilkoma gryfimi piórami.>$B$BWeź to, mon. Zanieś to do Orlego Gniazda, w sam środek miasta, przy studni. Wbij to! Wbij prosto w ziemię! Pokaż tym krasnoludom, że troll nie żartuje! Wróć, jak to zrobisz. Obyś $gwrócił żywy:wróciła żywa;.', 'Otho Moji\'ko z Wioski Odsłoniętego Kła w Zaziemiu chce, żebyś $gudał:udała; się do Orlego Gniazda w zachodniej części Zaziemia i $gumieścił:umieściła; ostatnią wiadomość do klanu Dzikiego Młota przy studni w centrum miasta. Wróć do niego, gdy wykonasz zadanie.$B$BStrzeż się rozzłoszczonych krasnoludów z klanu Dzikiego Młota i niesfornych członków Przymierza.', 'Wiadomość do klanu Dzikiego Młota dostarczona', 'Wróć do Otha Moji\'ko w Wiosce Odsłoniętego Kła w Zaziemiu.', '', '', '', '', 0),
(7844, 'plPL', 'Kanibalscy kuzyni', 'Zaziemie zamieszkują trzy różne plemiona trolli, $N. I na tym mniej więcej kończą się podobieństwa między nimi: wszyscy jesteśmy trollami i żyjemy w Zaziemiu.$B$BPlugawy Konar – trafna nazwa – to zdeprawowana banda; żywią się innymi trollami i humanoidami.$B$BGdyby Zul\'jin tu był, wybiłby ich wszystkich jednym ruchem nadgarstka – niestety, Zul\'jin jeszcze nie powrócił i musimy radzić sobie sami.$B$BTo od ciebie zależy, czy to plugastwo zniknie z tych stron!', 'Mistyczka Yayo\'jin z Wioski Odsłoniętego Kła w Zaziemiu chce, żebyś $gzabił:zabiła; 6 łowców skalpów Plugawego Konaru i 2 wróżbitów Plugawego Konaru. Wróć do niej, gdy wykonasz zadanie.$B$BYayo\'jin wskazała, że te trolle można znaleźć w pobliżu świątyń Shaol\'watha i Agol\'watha, w północnej części Zaziemia, ku północnemu wschodowi.', '', 'Wróć do mistyczki Yayo\'jin w Wiosce Odsłoniętego Kła w Zaziemiu.', '', '', '', '', 0),
(7845, 'plPL', 'Porwany Starszy Rozdarty Kieł!', 'Mój partner został porwany przez dzikusów z Plugawego Konaru podczas zuchwałego nocnego napadu na naszą wioskę. Nasi szpiedzy donieśli mi, że wciąż żyje i jest więziony na szczycie Jintha\'Alor. Podobno Plugawa kapłanka Hexx przygotowuje go na ofiarę dla Hakkara, Boga Krwi bez twarzy.$B$BMusisz go uratować, $N! Nasza wioska nie zniosłaby tak wielkiej straty.', 'Pierwotna Rozdarty Kieł z Wioski Odsłoniętego Kła w Zaziemiu chce, żebyś $guratował:uratowała; jej partnera, Starszego Rozdartego Kła, z Jintha\'Alor.$B$BPowiedziano ci, że jest więziony na szczycie Jintha\'Alor, stolicy Plugawego Konaru w południowej części Zaziemia.', '', '', '', '', '', '', 0),
(7846, 'plPL', 'Odzyskaj klucz!', 'Klucz do moich więzów ma Hitah\'ya Opiekunka. Jest w pobliskiej jaskini. Uważaj, $N, bo jest dobrze strzeżona.$B$BZabij ją i przynieś klucz, żeby zdjąć mi kajdany. Dopiero wtedy będę mógł wrócić do domu.', 'Starszy Rozdarty Kieł w Jintha\'Alor chce, żebyś $gzabił:zabiła; Hitah\'yę Opiekunkę i $gzdobył:zdobyła; klucz do kajdan, w które jest zakuty. Wróć do Starszego Rozdartego Kła, gdy odzyskasz klucz.', '', 'Wróć do Starszego Rozdartego Kła w Jintha\'Alor w Zaziemiu.', '', '', '', '', 0),
(7847, 'plPL', 'Powrót do Pierwotnej Rozdarty Kieł', 'Wróć do mojej partnerki, Pierwotnej Rozdarty Kieł, w Wiosce Odsłoniętego Kła. Powiedz jej, że wracam do domu! Z pewnością cię nagrodzi.', 'Starszy Rozdarty Kieł w Jintha\'Alor chce, żebyś $gwrócił:wróciła; do Pierwotnej Rozdarty Kieł w Wiosce Odsłoniętego Kła z wieścią o jego uratowaniu.', '', '', '', '', '', '', 0),
(7849, 'plPL', 'Lęk przed rozłąką', 'Jak wielu w naszej wiosce, i ja straciłem w dziczy ukochaną osobę. Niestety, był to mój brat bliźniak, Malkhor – porwany przez Plugawy Konar podczas tego samego napadu co Starszy Rozdarty Kieł.$B$BNie było mu pisane przeżyć; stracono go szybko i brutalnie, a jego szczątki rzucono na pożarcie szlamom i wilkom Plugawego Konaru.$B$BZa późno, by ocalić mu życie, ale nie za późno, by ocalić jego duszę. Odzyskaj jego szczątki, $N.', 'Myśliwy Markhor z Wioski Odsłoniętego Kła w Zaziemiu chce, żebyś $godzyskał:odzyskała; szczątki jego brata bliźniaka. Znajdź czaszkę myśliwego Malkhora oraz kości myśliwego Malkhora i przynieś je myśliwemu Markhorowi.$B$BMarkhor wspomniał, że szczątki jego brata rzucono na pożarcie szlamom i wilkom Plugawego Konaru. Wspomniał też, że w Jintha\'Alor jest dół na odpadki pełen szlamów, a także wilcze legowisko. Oba te miejsca są blisko szczytu świątyni.', '', 'Wróć do myśliwego Markhora w Wiosce Odsłoniętego Kła w Zaziemiu.', '', '', '', '', 0),
(7850, 'plPL', 'Mroczne naczynia', 'Plugawy Konar walczy z nadprzyrodzoną zajadłością. To sprawka nikczemnych magicznych splotów Plugawej kapłanki Hexx.$B$BW całym Jintha\'Alor znajdziesz mroczne naczynia ze skażoną krwią. Emanują one nikczemną magią Boga Krwi bez twarzy, wzmacniając trolle Plugawego Konaru i zarazem doprowadzając je do szaleństwa.$B$BUkradnij te naczynia i przynieś mi je, abym mogła usunąć skazę i ostatecznie rozluźnić uścisk Boga Krwi.', 'Pierwotna Rozdarty Kieł z Wioski Odsłoniętego Kła w Zaziemiu chce, żebyś $godzyskał:odzyskała; 5 naczyń ze skażoną krwią z Jintha\'Alor. Wróć do Pierwotnej Rozdarty Kieł, gdy wykonasz zadanie.', '', 'Wróć do Pierwotnej Rozdarty Kieł w Wiosce Odsłoniętego Kła w Zaziemiu.', '', '', '', '', 0),
(7861, 'plPL', 'Poszukiwani: Plugawa kapłanka Hexx i jej sługi', 'Z rozkazu Pierwotnej Rozdarty Kieł Plugawa kapłanka Hexx i jej sługi mają ponieść karę!$B$BWysoką nagrodę wyznaczono dla każdego, kto zabije Plugawą kapłankę Hexx i całą jej elitarną straż Aman\'zasi.', '$GOtrzymałeś:Otrzymałaś; rozkaz zabicia Plugawej kapłanki Hexx i 5 strażników Aman\'zasi Plugawego Konaru. Gdy wykonasz zadanie, zgłoś się do Pierwotnej Rozdarty Kieł w Wiosce Odsłoniętego Kła w Zaziemiu.$B$BPlugawą kapłankę Hexx i strażników Aman\'zasi znajdziesz na szczycie Jintha\'Alor w Zaziemiu.', '', 'Wróć do Pierwotnej Rozdarty Kieł w Wiosce Odsłoniętego Kła w Zaziemiu.', '', '', '', '', 0),
(7862, 'plPL', 'Oferta pracy: kapitan straży Wioski Odsłoniętego Kła', 'Po stracie kapitana straży Malkhora stanowisko kapitana straży Odsłoniętego Kła znów jest wolne. Jeśli chcesz zostać kapitanem straży Odsłoniętego Kła, wykonaj poniższe zadania i złóż podanie Pierwotnej Rozdarty Kieł:$B$BWytęp berserkerów Plugawego Konaru.$B$BWytęp łowców cieni Plugawego Konaru.$B$BWytęp krwiopijców Plugawego Konaru.$B$BWytęp pożeraczy dusz Plugawego Konaru.', 'Twoim zadaniem jest wybicie 5 berserkerów Plugawego Konaru, 3 łowców cieni Plugawego Konaru, 3 krwiopijców Plugawego Konaru i 2 pożeraczy dusz Plugawego Konaru.$B$BGdy wykonasz to zadanie, wróć do Pierwotnej Rozdarty Kieł w Wiosce Odsłoniętego Kła w Zaziemiu.', '', 'Wróć do Pierwotnej Rozdarty Kieł w Wiosce Odsłoniętego Kła w Zaziemiu.', '', '', '', '', 0),
(8643, 'plPL', 'Nestor Wysoki Szczyt', '', '', '', '', '', '', '', '', 0),
(9469, 'plPL', 'Poparcie Pierzastobrodego', 'Kiedy w końcu otrzymam audiencję u Falstada Dzikiego Młota, chciałbym mieć u boku naszego najsilniejszego orędownika wśród krasnoludów z klanu Dzikiego Młota, $N.$B$BPierzastobrody cieszy się wśród swoich wielkim szacunkiem, zarówno za legendarną umiejętność układania gryfów, jak i za swoją mądrość. Jeśli ktokolwiek może przekonać Falstada Dzikiego Młota, to właśnie on.$B$BSam bym do niego poszedł, ale czekając na audiencję, nie mogę opuszczać Orlego Gniazda. Odwiedź Pierzastobrodego w jego domu na południu i zapytaj, czy zechce ze mną porozmawiać.', 'Udaj się do Lepianki Pierzastobrodego i odwiedź krasnoluda, jeśli jest w domu. Jeśli go nie ma, poszukaj wskazówek, gdzie można go znaleźć.', '', '', '', '', '', '', 0),
(9470, 'plPL', 'Gest dobrej woli', 'Surowe tereny Zaziemia są domem nie tylko dla krasnoludów z klanu Dzikiego Młota i ich gryfów, ale też dla wielu plemion leśnych trolli.$B$BTrolle uważają Dzikie Młoty za intruzów na ziemiach swoich przodków i nie przepuszczają żadnej okazji, by nękać krasnoludy, atakując gryfie gniazda. Jednym ze sposobów, by wykazać się w oczach Dzikich Młotów, jest pomoc w powstrzymaniu tych ataków przez zabicie przywódcy Suchokorych, znachora Mai\'jina, który kryje się w jaskini na Występie Bogena, na zachód od Shadra\'Alor.', 'Ambasador Rualeth z Orlego Gniazda chce, żebyś $gzabił:zabiła; znachora Mai\'jina i jego pająka Tcha\'kaza.', '', 'Wróć do ambasadora Rualetha w Orlim Gnieździe w Zaziemiu.', '', '', '', '', 0),
(9471, 'plPL', 'Polowanie na drapieżników', 'Krasnoludy z klanu Dzikiego Młota są dla gryfów towarzyszami, opiekunami i treserami. Gryfy nie narzekają na brak wrogów, zwłaszcza wśród plemion leśnych trolli.$B$BCzasem jednak zagrożenie stanowią naturalne drapieżniki, takie jak wilki. Pojedyncze zwierzę nie ma szans z gryfem, ale sfory coraz częściej atakują gryfy, bo zwykłej zwierzyny jest mało. Przetrzebienie wilków może zmniejszyć zagrożenie dla gryfów i zjednać nam przychylność Dzikich Młotów.', 'Ambasador Rualeth z Orlego Gniazda chce, żebyś $gzabił:zabiła; 10 parszywych srebrnogrzywych wilków i 5 srebrnogrzywych wilków.', '', 'Wróć do ambasadora Rualetha w Orlim Gnieździe w Zaziemiu.', '', '', '', '', 0),
(9475, 'plPL', 'Odzyskanie jaj', 'Oglądając szczątki, dochodzisz do wniosku, że ten połamany i zmasakrowany szkielet to wszystko, co zostało z Pierzastobrodego. W kościstej dłoni ściska podarty i poplamiony plik papierów. Ostrożnie go wyjmujesz i rozwijasz – to ręcznie rysowana mapa i kilka pospiesznie nabazgranych notatek.$B$BMapa przedstawia chyba Shadra\'Alor i jego trzy świątynie; w kilku miejscach widnieją znaki „x”, zapewne tam, gdzie są skradzione jaja. Chowasz mapę do plecaka, by obejrzeć ją w bezpieczniejszym miejscu.', 'Zbierz 5 jaj gryfa i zanieś je ambasadorowi Rualethowi w Orlim Gnieździe.', '', 'Wróć do ambasadora Rualetha w Orlim Gnieździe w Zaziemiu.', '', '', '', '', 0),
(9476, 'plPL', 'Śladami Pierzastobrodego', 'Najnowsze wpisy w dzienniku opisują niepokój Pierzastobrodego z powodu coraz liczniejszych napadów trolli Suchokorych na gryfie gniazda Dzikich Młotów i fali kradzieży jaj. Przeszukanie mniejszych osad Suchokorych w okolicy najwyraźniej nic nie dało.$B$BOstatni wpis opisuje podejrzenie Pierzastobrodego, że za napadami stoi znachor Suchokorych imieniem Mai\'jin. Ostatnie, pospiesznie zapisane zdanie mówi o zamiarze krasnoluda, by udać się do Shadra\'Alor na poszukiwanie jaj.', 'Udaj się do Shadra\'Alor i poszukaj śladów Pierzastobrodego.', '', '', '', '', '', '', 0);
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(77, 'plPL', 'Znakomicie wykonane, $N. Cieszę się, że $gwykazałeś:wykazałaś; się dość dużą przezornością, by nie naruszyć delikatności sikacza. Nie ma nic gorszego niż bukiet sikacza, którym niepotrzebnie trzęsiono.$b$bCzarowanie tego cennego ładunku zajmie chwilę. Właściwie to żadna magia nie wchodzi w grę; po prostu mam trochę pustych opakowań po miodowym sikaczu z Zaziemia. Nasz fortel zmieni te butelki w alkoholowy skarb wszech czasów.$b$bNaprzód – po wielką gorzałę!', 0),
(485, 'plPL', 'Umieszczasz jajo... sygnalizator alarmowy... wewnątrz kurczaka... samonaprowadzającego robota.$b$bZe środka robota dobiega buczenie i warkot, gdy ten usiłuje wstać. Kiedy robot ożywa, znów słychać głos Oglethorpe\'a, tym razem z jego wnętrza:$b$b„OOX-09/HL przynajmniej działa, ale wymaga poważnej naprawy! Jest o wiele za ciężki, żebyś $gmógł:mogła; go nieść... ale chyba mam pewien pomysł. Popilnujesz go jeszcze trochę?”', 0),
(1446, 'plPL', 'Ślepa wiara Jammal\'ana w fałszywe wizje doprowadziła mój lud do wiecznej zguby.$b$bDziękuję ci, $N, że $gpomściłeś:pomściłaś; moje wygnanie. Opłakuję mój lud. Nie mam domu, do którego mógłbym wrócić.', 0),
(1450, 'plPL', 'Ach, tak. Oczywiście, że pamiętam, jak wysłałem jednego z moich jeźdźców gryfów do pomocy Brohannowi Beczkobrzuchowi.$B$BZawsze miałem słabość do Ligi Odkrywców. Prawdę mówiąc, mój ojciec pomagał pierwszej ekipie wykopaliskowej, która odkryła Uldaman.$B$BWysłałem z Brohannem tego, kogo wtedy uważałem za najlepszego jeźdźca gryfów. Był to gość imieniem Rhapsody Shindigger.$B$BA co to był za dżokej gryfów! No, dopóki...', 0),
(1451, 'plPL', 'Hep!$B$BPatrzę prosto na ciebie, a ty ciągle podskakujesz w górę i w dół. Aż mi się w głowie kręci. Hoho!$B$BHep!$B$BOjej! Czujesz to? Ziemia się trzęsie, $gprzyjacielu:przyjaciółko;. Muszę się napić.$B$BHep!', 0),
(1452, 'plPL', 'Widzę, że bez żadnego kłopotu $gzdobyłeś:zdobyłaś;, czego mi trzeba! Musiała to być niezła wyprawa tam, do dalekiego Kalimdoru.$B$BWyciągnięcie z tych żołądków i wątrób tego, czego potrzebuję, zajmie mi tylko chwilkę. Hep!$B$BPotem wydestyluję sobie srogi trunek i wreszcie powiem ci, co chcesz wiedzieć.$B$BHep!$B$BAż mnie ciarki przechodzą na samą myśl o tamtych bagnach.$B$BHep!$B$BDaj mi szybciutko zmieszać drinka.', 0),
(2742, 'plPL', 'Ta trollowa tablica musi być „sekretem”, o którym mówił Rin\'ji.$B$BPokrywają ją dziwne znaki; nie potrafisz odczytać, co jest na niej napisane.', 0),
(2877, 'plPL', 'No proszę, pomagasz Dzikim Młotom! Z ciebie osoba czynu, a czyny to coś, co tu szanujemy.$B$BTwoja drobna misja sprzątająca jest o wiele ważniejsza, niż ci się może wydawać. Skoro ktoś przerzedza szlamy i breje, w mig rozszerzymy naszą strefę wpływów. Masz – weź coś jeszcze, oprócz tego, że zyskujesz nowych przyjaciół tu, w Orlim Gnieździe!', 0),
(2880, 'plPL', 'I o to właśnie chodzi! Widzisz – te naszyjniki dowodzą, że nie boisz się pobrudzić sobie rąk. My, Dzikie Młoty, cenimy to u tych, z którymi się zadajemy.$B$BTak trzymaj, a jeszcze zyskasz naszą przychylność.', 0),
(2881, 'plPL', 'I o to właśnie chodzi! Widzisz – te naszyjniki dowodzą, że nie boisz się pobrudzić sobie rąk. My, Dzikie Młoty, cenimy to u tych, z którymi się zadajemy.$B$BTak trzymaj, a jeszcze zyskasz naszą przychylność.', 0),
(2988, 'plPL', 'Ostrodziobej nie było w wioskach? Hm... to ponure wieści. Temu młodemu gryfowi pisane jest poprowadzić następne pokolenie gryfów. Jeśli go stracimy, siła i duch naszej floty ogromnie ucierpią.', 0),
(2989, 'plPL', 'Nie było tam Ostrodziobej? To zła wiadomość, ale i dobra...$B$BDobrze, że nie było jej przy Ołtarzu Zula, bo trolle Plugawego Konaru słyną ze składania ofiar.$B$BDziękuję ci za całą pomoc, ale obawiam się, że przed nami jeszcze większe zadanie.', 0),
(2990, 'plPL', 'Ach, tak. To pióro należy do wspaniałego gryfa. Takiego, któremu pisane są wielkie rzeczy... jeśli zdoła bez szwanku dożyć dorosłości.$B$BChcesz odnaleźć to pisklę? W takim razie słuchaj uważnie, $gśmiałku:śmiałkini;...', 0),
(2992, 'plPL', 'Rytuał się powiódł. Widziałem Ostrodziobą i mogę ci powiedzieć, jak ją odnaleźć.', 0),
(2993, 'plPL', '$GRozmawiałeś:Rozmawiałaś; z Ponurym Cieniem? Co powiedział?$B$B...Co? Trolle Plugawego Konaru mają Ostrodziobą? To nie do zniesienia! Musimy zebrać oddział i ją odbić!', 0),
(2994, 'plPL', 'Rączy Wiatr i Bystry Pazur wrócili chwilę temu ze swoim dzieckiem i trzęsą się nad nim jak świeżo upieczeni rodzice. Widok ich znów razem wystarczy, by nawet takiemu staremu krasnoludowi zakręciła się łza w oku...$B$BNigdy nie zdołamy ci się odwdzięczyć za to, co $gzrobiłeś:zrobiłaś;, $N. Gryfy z Orlego Gniazda i ich jeźdźcy będą długo, bardzo długo wyśpiewywać twoje imię.', 0),
(4297, 'plPL', 'Te się świetnie nadadzą, a jeśli się nie mylę, twoje jajeczko zaraz się wykluje. Jakie to uczucie? No wiesz, że zaraz $gzostaniesz ojcem:zostaniesz matką;? Haha, nie $gmyślałeś:myślałaś;, że przyjdzie ci dźwigać taką odpowiedzialność, co?', 0),
(4298, 'plPL', 'Masz, weź jajo... lepiej, żeby było u ciebie, to się do ciebie przywiąże i będzie cię uważać za $gtatusia:mamusię;.$B$BGratulacje, $N. Jesteś rodzicem... tak jakby.', 0),
(4787, 'plPL', 'Ach, masz jajo! Kłaniam ci się, $N. Twoja siła i odwaga zostaną zapamiętane na długo.', 0),
(7815, 'plPL', 'Och, mon! Nie wiem, jak ci dziękować! Mam nadzieję, że ta wędka będzie wystarczającą nagrodą za tę robotę.', 0),
(7816, 'plPL', 'MON! To fantastyczne! Z moją najlepszą przynętą i z mniejszą liczbą kłapaczy ryby same będą się pchać na haczyk.', 0),
(7828, 'plPL', 'Dobra robota, $N. Plemię Odsłoniętego Kła dziękuje ci za twój wkład.', 0),
(7829, 'plPL', '$GOkazałeś:Okazałaś; się $ggodnym sojusznikiem:godną sojuszniczką; Odsłoniętego Kła, $N. Dobra robota.', 0),
(7830, 'plPL', '<Markhor ogląda pióro.>$B$BCiekawe, ilu naszych łowców pożarła ta bestia, zanim $gwymierzyłeś:wymierzyłaś; jej sprawiedliwość.', 0),
(7839, 'plPL', 'Moje narzędzia! $GZnalazłeś:Znalazłaś; je! Och, cóż za wspaniały dzień! Dziękuję ci, $N.', 0),
(7840, 'plPL', '<Smalec bierze od ciebie ogromny udziec mięsa i wpycha go sobie do gęby.>$B$BTo było to! Dzięki, $gmały:mała;.$B$BSmalec zrobić ci specjalny koszyk piknikowy, bo ty pomóc Smalcowi.', 0),
(7841, 'plPL', 'Wygląda na to, że Odsłonięty Kieł też zawiera nowe sojusze, mon! Dobrze się $gspisałeś:spisałaś;.', 0),
(7842, 'plPL', 'Och, mon, to będzie dobre. Jeszcze jeden krok i Dzikie Młoty zobaczą, że z trollem się nie zadziera!', 0),
(7843, 'plPL', 'Szkoda, że nie mogłem widzieć ich min, mon. Pakują manatki? Wynoszą się z miasta?$B$BDobrze się $gspisałeś:spisałaś;, $N. Naprawdę dobrze. Otho nagrodzi cię wielkim mojo.', 0),
(7844, 'plPL', 'Dobra robota, $N. Sam Zul\'jin nie zrobiłby tego lepiej!', 0),
(7845, 'plPL', 'Musisz działać szybko, $N. Straże z pewnością już wiedzą o twojej obecności.', 0),
(7846, 'plPL', 'Nareszcie wolność! Dziękuję ci, $N. Odsłonięty Kieł pozna twoje czyny!', 0),
(7847, 'plPL', '$GOddałeś:Oddałaś; plemieniu Odsłoniętego Kła wielką przysługę, $N! Mamy wobec ciebie wielki dług wdzięczności.', 0),
(7849, 'plPL', 'Mój najdroższy bracie, jakże będzie mi cię brakowało...$B$BDziękuję ci za pomoc, $N. W moich oczach jesteś $gprawdziwym bohaterem:prawdziwą bohaterką;.', 0),
(7850, 'plPL', 'Mroczna energia, która napędza Plugawy Konar, została zdjęta – na razie. Musimy zachować czujność w naszej walce ze złem, bo nawet jeśli Plugawa kapłanka zostanie zniszczona, jej miejsce wkrótce zajmie inna.', 0),
(7861, 'plPL', 'To rzeczywiście druzgocący cios dla Plugawego Konaru. Zostaniesz sowicie $gnagrodzony:nagrodzona;, $N.', 0),
(7862, 'plPL', 'Rzeczywiście jesteś $ggodnym kandydatem:godną kandydatką; na nowe stanowisko, $N. Przyjmij ten drobiazg w dowód uznania dla twojej ciężkiej pracy. Wszystkie podania rozpatrzę w przyszłym roku.', 0),
(9469, 'plPL', 'W dzienniku Pierzastobrodego jest sporo niedawnych wpisów. Cofając się do początku najnowszych, zaczynasz szukać wskazówek, dokąd mógł się udać.', 0),
(9470, 'plPL', 'Dobra robota, $N. Dzikie Młoty nabiorą otuchy, gdy się dowiedzą, że nie stoją same przeciwko trollom Suchokorych. Pokazanie im, że Przymierze może być niezawodnym partnerem w ochronie gryfów, powinno dodać wagi naszej propozycji.', 0),
(9471, 'plPL', '<Ambasador Rualeth kiwa głową, gdy składasz raport.>$B$BDobrze się $gspisałeś:spisałaś;. Przetrzebienie srebrnogrzywych wilków nie ujdzie uwadze Dzikich Młotów. Jestem pewien, że gdy spotkam się z ich przywódcami, twoje czyny dobrze będą świadczyć o Przymierzu. Przyjmij, proszę, tę monetę jako skromny wyraz mojej wdzięczności, $N.', 0),
(9475, 'plPL', '<Wręczając jaja ambasadorowi, opisujesz, co $gznalazłeś:znalazłaś; w Lepiance Pierzastobrodego i w Shadra\'Alor.>$B$BSuchokorzy zabili Pierzastobrodego?$B$B<Twarz Rualetha wykrzywia się z przerażenia, gdy opisujesz śmierć krasnoluda i to, co oznacza ona dla jego misji.>$B$BRozumiem, czemu uważał, że musi wyruszyć na poszukiwanie jaj, ale szkoda, że nie pomyślał, by zabrać ze sobą innych. Jego śmierć bez wątpienia rozwścieczy Falstada Dzikiego Młota, wywoła odwet na trollach i odsunie moją audiencję na czas nieokreślony.', 0),
(9476, 'plPL', 'Na ołtarzu leży stos kości, które najwyraźniej należały do krasnoluda. Nie zostały żadne cechy pozwalające go rozpoznać, ale postanawiasz przeszukać ciało, by upewnić się, że to szczątki Pierzastobrodego.', 0),
(11755, 'plPL', 'Zbezcześć wielkie ognisko Przymierza w Zaziemiu!', 0),
(11784, 'plPL', 'Zbezcześć wielkie ognisko Hordy w Zaziemiu!', 0),
(11826, 'plPL', 'Uczcij płomień Zaziemia!', 0),
(11860, 'plPL', 'Uczcij płomień Zaziemia!', 0);
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES
(77, 'plPL', 'Ufam, że $gprzybyłeś:przybyłaś; do naszego obozu, by dostarczyć butelki sikacza niezbędne do wykonania zadania, czyż nie?', 0),
(485, 'plPL', 'Wygląda na to, że $gnatrafiłeś:natrafiłaś; na wrak... robotycznego kurczaka? Z wnętrza jaja znów dobiega trzeszczący głos:$b$b„Tak, świetna robota! To rzeczywiście mój samonaprowadzający robot, choć czujniki wskazują, że zanim poleci na naprawę do Łupieżczej Zatoki, trzeba go pobudzić do życia. Śmiało, umieść sygnalizator w łaziku – resztą zajmie się sygnalizator!”', 0),
(1446, 'plPL', 'Gdy Jammal\'an zostanie usunięty, będę mieć szansę wrócić do mojego ludu.$b$bPod duchowym przywództwem Jammal\'ana Atal\'ai czeka pewna zagłada.', 0),
(1452, 'plPL', '$GPiłeś:Piłaś; kiedyś słód „Rapsodia”? Jeden z moich najlepszych trunków, choć to nieskromnie mówić. Hep!$B$BAle jeśli mam na nowo przeżyć grozę tamtego feralnego lotu nad... hep... bagnami, to będę potrzebował czegoś odrobinkę mocniejszego. Hep!$B$BNie $gznalazłeś:znalazłaś; przypadkiem tych żołądków i wątrób, które dodadzą mojemu Kalimdorskiemu Koktajlowi kopa?$B$BHep!', 0),
(2742, 'plPL', 'Rin\'ji się boi!', 0),
(2766, 'plPL', 'Wygląda na to, że $gnatrafiłeś:natrafiłaś; na wrak... robotycznego kurczaka? Z wnętrza jaja znów dobiega trzeszczący głos:$b$b„Tak, świetna robota! To rzeczywiście mój samonaprowadzający robot, choć czujniki wskazują, że zanim poleci na naprawę do Łupieżczej Zatoki, trzeba go pobudzić do życia. Śmiało, umieść sygnalizator w łaziku – resztą zajmie się sygnalizator!”', 0),
(2877, 'plPL', 'Nawet nie próbuj negocjować tej misji, $r! Gdyby bogowie chcieli, żeby te szlamy zginęły, to już dawno by je cudem wybili, nie?!', 0),
(2880, 'plPL', 'Chcę pięciu tych plemiennych naszyjników, które trolle noszą przy sobie. Jeśli trzeba ci to wyłożyć jaśniej: jak któregoś zabijesz, masz spore szanse jeden zdobyć!$B$BUdowodnij swoją wartość Dzikim Młotom!', 0),
(2881, 'plPL', 'Chcę pięciu tych plemiennych naszyjników, które trolle noszą przy sobie. Jeśli trzeba ci to wyłożyć jaśniej: jak któregoś zabijesz, masz spore szanse jeden zdobyć!$B$BUdowodnij swoją wartość Dzikim Młotom!', 0),
(2988, 'plPL', '$GPrzeszukałeś:Przeszukałaś; klatki, $N? Musimy odnaleźć Ostrodziobą!', 0),
(2989, 'plPL', 'Pospiesz się, $N! Jeśli trolle Plugawego Konaru mają Ostrodziobą, to kto wie, co z nią robią!', 0),
(2990, 'plPL', '$N, przychodzisz z darem?', 0),
(2994, 'plPL', 'Uratuj Ostrodziobą!', 0),
(4297, 'plPL', 'Masz już to mięso, $N? Twoje jajeczko zaraz się wykluje. Jeśli maluch nie dostanie porządnego pierwszego posiłku, może nie przeżyć pierwszego tygodnia, a nie chciałbym, żeby tak się stało.$B$BNie będę cię okłamywał, $N. Zazdroszczę ci, że w ogóle dostało ci się to jajo. Nie każ mi żałować, że ci tak pomagam.', 0),
(4787, 'plPL', 'Masz prastare jajo? Wyczuwam poruszenie wielkich sił i obawiam się, że czasu jest coraz mniej.', 0),
(7816, 'plPL', 'Masz ją już?', 0),
(7828, 'plPL', 'Pokaż im potęgę Odsłoniętego Kła!', 0),
(7829, 'plPL', 'Oczyść umysł z nieczystych myśli, $N. Stań się jednością z dziczą!', 0),
(7830, 'plPL', 'Brzytwodzioby władca przestworzy to o wiele rzadszy gatunek gryfa: to on odpowiada za rozmnażanie i płodzenie morderczego potomstwa.', 0),
(7839, 'plPL', 'Uważaj na trolle Plugawego Konaru w okolicy, $N. To bezwzględne, mordercze plugastwo.', 0),
(7840, 'plPL', '<Smalec pociera swój ogromny brzuch.>$B$BSmalec taki głodny.', 0),
(7841, 'plPL', 'Jesteś za $gczysty:czysta;, mon. Musisz się zmieszać z wrogiem – ubrudzić się porządnie.', 0),
(7842, 'plPL', 'Ostatnia wiadomość na pewno ich przepędzi. Albo przynajmniej bardzo, bardzo rozzłości.', 0),
(7843, 'plPL', 'Na co czekasz, mon?', 0),
(7844, 'plPL', 'Wróżbici i łowcy skalpów Plugawego Konaru zamieszkują północną część Zaziemia, ku północnemu wschodowi.', 0),
(7846, 'plPL', 'Musisz się spieszyć!', 0),
(7849, 'plPL', 'Gdy dostanę jego szczątki, zaniosę je do Yayo\'jin, żeby przygotowała je do godnego pochówku.', 0),
(7850, 'plPL', 'Uważaj w walce z Plugawym Konarem, $N. Ich umysły są zamroczone – walczą do śmierci.', 0),
(7861, 'plPL', 'Przynosisz wieści z Jintha\'Alor?', 0),
(7862, 'plPL', 'Przychodzisz w sprawie oferty pracy?', 0),
(9470, 'plPL', 'Wracasz z wieścią o śmierci znachora Mai\'jina?', 0),
(9471, 'plPL', '$GPrzetrzebiłeś:Przetrzebiłaś; już srebrnogrzywe wilki?', 0),
(9475, 'plPL', 'Wyraz twojej twarzy zdradza, że przynosisz złe wieści. Czego się $gdowiedziałeś:dowiedziałaś;?', 0);
