INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES
(2907, 'plPL', 'Szkic przedstawia Shadra\'Alor i jego trzy świątynie; kilka znaków „x” oznacza miejsca, w których są skradzione jaja. Znaki widnieją na południowym krańcu wschodniej świątyni, obok chaty na północny wschód od wschodniej świątyni, przy ołtarzu na wschód od centralnego jeziora oraz na zboczu południowej świątyni, przy słowie „wygnaniec”.$B$BZ notatek Pierzastobrodego wynika, że zamierzał przekazać te informacje Falstadowi Dzikiemu Młotowi w nadziei, że ten wyśle oddział wojowników na ratunek jajom.', 0);
