INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(3787, 'plPL', 'Rin\'ji wolny!', '', 0),
(3790, 'plPL', 'Rin\'ji widzi już drogę, $n. Rin\'ji zna drogę do domu.', '', 0),
(3817, 'plPL', 'Rin\'ji zdradzi ci teraz sekret... $n $gpowinien:powinna; iść na Urwiska Widokowe. Rin\'ji ukrył coś na tamtejszej wyspie.', '', 0),
(3818, 'plPL', 'Znajdziesz, to twoje! Nie mów nikomu, że Rin\'ji z tobą gadał!', '', 0),
(3827, 'plPL', '', 'Do ataku, siostry! Troll nie może uciec!', 0),
(3861, 'plPL', 'Rin\'ji jest atakowany!', '', 0),
(3862, 'plPL', 'Rin\'ji potrzebuje pomocy!', '', 0),
(4126, 'plPL', 'Podczas rytuału nie wydawaj żadnego dźwięku. Jeden fałszywy krok może oznaczać naszą zgubę...', '', 0),
(4127, 'plPL', 'A teraz patrz...', '', 0),
(4128, 'plPL', 'Proszę. Gotowe.', '', 0),
(4138, 'plPL', '', '%s ćwierka na pożegnanie, a $n odprowadza ją wzrokiem.', 0),
(8051, 'plPL', 'Z materiałów, które tu znajduję, potrafię robić niesamowite rzeczy. Na brodę Muradina, na tych wzgórzach żyją fantastyczne stworzenia! Idź, spróbuj się z nimi zmierzyć, $n, i wróć z jakimiś niestworzonymi historiami.', '', 0),
(9863, 'plPL', 'Nie widzisz, że łowię ryby!', '', 0),
(9864, 'plPL', '$GSpłoszyłeś:Spłoszyłaś; mi ryby! Czego chcesz?', '', 0),
(9865, 'plPL', 'Co mogę dla ciebie zrobić, $N?', '', 0),
(9866, 'plPL', 'Zostanę tu, dopóki nie złowię granika ważącego 68 funtów! Ty za to chcesz gdzieś polecieć, mam rację?', '', 0),
(9926, 'plPL', 'Smalec pilnować tu spokoju. Smalec też sprzedawać ryby. Chcesz ryba?', 'Smalec pilnować tu spokoju. Smalec też sprzedawać ryby. Chcesz ryba?', 0),
(9975, 'plPL', 'Mam wszystkie zapasy kucharskie, jakich kiedykolwiek będziesz potrzebować, mon!', '', 0),
(9977, 'plPL', 'Jak coś zepsute, to Żużlodrzew naprawi!', '', 0),
(9979, 'plPL', 'Wędkowanie jest takie przyjemne, mon. Wiesz? Swój stan błogości zawdzięczam mojemu mistrzowi, największemu wędkarzowi na całym świecie – Natowi Pagle\'owi. $GSłyszałeś:Słyszałaś; o nim, mon?$B$BJeśli szukasz oświecenia, to Nat Pagle wskaże ci drogę.', '', 0),
(9980, 'plPL', 'Czego możesz mnie nauczyć?', 'Czego możesz mnie nauczyć?', 0),
(9981, 'plPL', 'Zul\'jin pewnego dnia powróci, $N. Zapamiętaj moje słowa. Do tego czasu wszyscy trzymamy swoje pozycje i robimy, co możemy, by ocalić populację leśnych trolli.$B$BA skoro już o tym mowa, jako główny łowczy Wioski Odsłoniętego Kła odpowiadam za to, by świat wokół nas nadawał się do życia.$B$BBestie w tej okolicy trzeba trzymać w ryzach.$B$BSzukasz pracy?\n', '', 0),
(10012, 'plPL', 'Zdobądź klucz i otwórz te łańcuchy! Ma go Hitah\'ya Opiekunka... w głębi jaskini...', '', 0),
(10013, 'plPL', 'Nareszcie jestem wolny! Niedługo wrócę do domu, moja droga!', '', 0),
(10882, 'plPL', 'Wasze nikczemne dusze zasilą moją moc!', '', 0),
(10883, 'plPL', 'Wyczuwam CIEŃ w waszych sercach. Dla nikczemnych nie ma spoczynku!', '', 0),
(13628, 'plPL', 'Dzień dobry, $N.$B$BCzekam na wiadomość od jednego z doradców wielkiego thana w sprawie audiencji. Samo uzyskanie możliwości przedstawienia listów uwierzytelniających kosztowało mnie sporo wysiłku.$B$BSłyszałem, że Dzikie Młoty określa się jako „nieufne wobec obcych”, ale okazało się to sporym niedopowiedzeniem. Mam nadzieję, że sytuacja się poprawi, gdy już spotkam się z Pierzastobrodym, który podobno opowiada się za bliższymi więzami z Przymierzem.', '', 0),
(43282, 'plPL', 'Witaj w Orlim Gnieździe, domu Klanu Dzikiego Młota.$B$BSkoro wielki than Falstad siedzi w Żelaznej Kuźni, będziesz mieć do czynienia ze mną.', '', 0);
